// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Precondition: arrays must be non-empty and of same length
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Bound v values to avoid overflow in multiplication
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000);
        }
        // Impersonate the from address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Call transfer
        c.transfer(_tos, v);
        // Rule: caddress must remain the original immutable value
        assertTrue(c.caddress() == 0x1f844685f7Bf86eFcc0e74D8642c54A257111923);
    }
}

